// STORES ve HANS'ı yeni alanlarla zenginleştir — eksik alanlar nötr varsayılana düşer.
const NEUTRAL_EXT = {
  location:{ street:null, gate:null, landmark:null, side:null },
  trade:{ type:"perakende", minOrder:{qty:1, amount:0}, negotiable:true, isProducer:false, moqFlexible:true, tiers:[] },
  commerce:{ taxFree:false, invoice:true, payments:["cash"], currencies:["TRY"], languages:["tr"] },
  exportInfo:{ shipsAbroad:false, countries:[], partners:[], customsSupport:false, consolidation:false },
  production:{ monthlyCapacity:"—", leadTimeDays:"—", oem:false, privateLabel:false, certs:[] },
  catalogPdf:false
};

// Saat modeli: rozet ("Açık · 40 dk sonra kapanıyor"), haftalık tablo ve kartta yazan
// "hours" metni TEK kaynaktan üretilir. Daha önce her dükkâna aynı varsayılan takvim
// atanıyordu; kart 09:30 derken rozet 08:30'a göre hesaplıyordu.
const toMin = (t) => { const [h, m] = t.split(":").map(Number); return h * 60 + m; };
const fromMin = (v) => String(Math.floor(v / 60)).padStart(2, "0") + ":" + String(v % 60).padStart(2, "0");
const shiftT = (t, d) => fromMin(Math.max(0, Math.min(24 * 60 - 1, toMin(t) + d)));

function buildHours(s, areaId) {
  const m = String(s.hours || "").match(/(\d{1,2}:\d{2})\s*[–\-]\s*(\d{1,2}:\d{2})/);
  const open = m ? m[1] : "09:00", close = m ? m[2] : "19:00";
  const wd = [open, close];
  // Mısır Çarşısı ve cadde dükkânları pazar da açık (kısa gün); han/Kapalıçarşı pazar kapalı.
  const sundayOpen = areaId === "misircarsisi" || (!s.han && areaId !== "kapalicarsi");
  const sat = [open, shiftT(close, areaId === "misircarsisi" ? 0 : -60)];
  const sun = sundayOpen ? [shiftT(open, 60), shiftT(close, -180)] : null;
  return {
    weekly: [sun, wd, wd, wd, wd, wd, sat],
    // Cuma namazı arası yalnızca han içi esnafta uygulanır.
    fridayBreak: s.han ? HOURS_DEFAULT.fridayBreak : null,
    ramadan: HOURS_DEFAULT.ramadan,
    holidays: HOURS_DEFAULT.holidays
  };
}

STORES.forEach(s => {
  const ext = SHOP_EXT[s.id] || {};
  Object.keys(NEUTRAL_EXT).forEach(k => { s[k] = ext[k] || NEUTRAL_EXT[k]; });
  s.seasonTr = ext.seasonTr || null; s.seasonEn = ext.seasonEn || null;
  s.seasonRu = ext.seasonRu || null; s.seasonAr = ext.seasonAr || null;
  const hanRec = s.han ? HANS.find(h => h.id === s.han) : null;
  s.hours2 = buildHours(s, hanRec ? hanRec.area : s.area);
  if (s.han && HAN_EXT[s.han]) s.location = { ...s.location, gate: s.location.gate || HAN_EXT[s.han].entryGate };
});

// Sokak grafiği çift yönlü olmalı: veri tek yönlü girildiği için burada simetrikleştiriyoruz.
// Aksi halde çarşı içi sokaklardan dışarıya BFS yol bulamaz.
STREETS.forEach(a => (a.neighbors || []).slice().forEach(nid => {
  const b = STREETS.find(x => x.id === nid);
  if (b && !(b.neighbors || []).includes(a.id)) (b.neighbors = b.neighbors || []).push(a.id);
}));

HANS.forEach(h => { Object.assign(h, HAN_EXT[h.id] || { entryGate:null, entryStreet:null, courtyard:"square", stairs:1, lift:false, wc:false, tea:false, landmark:null, floorNames:{} }); });

// id → nesne kısayolları
export const byId = (list, id) => list.find(x => x.id === id) || null;
export const GATE = id => byId(GATES, id);
export const STREET = id => byId(STREETS, id);
export const LANDMARK = id => byId(LANDMARKS, id);
export const HAN = id => byId(HANS, id);
export const SHOP = id => byId(STORES, id);
export const t4 = (o, lang) => o ? (o[lang] ?? o.tr ?? "") : "";


