// Special:FilePath kalıcı yönlendirme kullanır; hash yolu gerekmez.
export const PHOTO_BASE = "https://commons.wikimedia.org/wiki/Special:FilePath/";
export const photoUrl = (file, w) =>
  PHOTO_BASE + encodeURIComponent(String(file).replace(/ /g, "_")) + "?width=" + (w || 900);

